    count_dept = {}
    for e in employees:
        dept = e.get("dept")
        if e.get("senior"):
            count_dept[dept] = count_dept.get(dept, 0) + 1
    return count_dept

def avg_salary_by_dept(employees):
    totals = {}
    counts = {}
    for e in employees:
